	"guidedRuns.easy30.subtitle": "Voz do treinador · 30 min · esforço leve",
	"guidedRuns.easy30.description": "Uma corrida tranquila em ritmo de conversa, para um dia de recuperação ou só para clarear a cabeça. O treinador aparece a cada cinco minutos com um empurrãozinho gentil.",
	"guidedRuns.easy30.cue0": "Vamos lá. Comece leve — este é o seu ritmo de recuperação.",
