	"guidedRuns.easy30.cue2": "Dez minutos. Verifique a cadência — pés rápidos, pisada leve.",
	"guidedRuns.easy30.cue3": "Metade. Ainda deve conseguir conversar enquanto corre.",
	"guidedRuns.easy30.cue4": "Vinte minutos. Observe a respiração — inspire devagar pelo nariz, expire pela boca.",
	"guidedRuns.easy30.cue5": "Faltam cinco minutos. Mantenha-se relaxado. Não acelere.",
	"guidedRuns.easy30.cue6": "Falta um minuto. Termine leve.",
	"guidedRuns.easy30.cue7": "Concluído. Caminhe um minuto para recuperar. Mandou bem.",
	"guidedRuns.tempo25.title": "Construtor de tempo de 25 minutos",
	"guidedRuns.tempo25.subtitle": "Voz do treinador · 25 min · 5-15-5",
	"guidedRuns.tempo25.description": "Cinco minutos de aquecimento leve, quinze minutos em tempo (confortavelmente forte), cinco minutos de desaquecimento. A clássica sessão de tempo semanal.",
	"guidedRuns.tempo25.cue0": "Hora do aquecimento. Cinco minutos leves — acorde as pernas.",
	"guidedRuns.tempo25.cue1": "Falta um minuto de aquecimento. Aumente a cadência.",
	"guidedRuns.tempo25.cue2": "Suba para o tempo. Confortavelmente forte. Como um esforço de prova de 10K.",
	"guidedRuns.tempo25.cue3": "Cinco minutos em tempo. Forte, mas controlado. Mantenha o ritmo.",
	"guidedRuns.tempo25.cue4": "Dez minutos de tempo feitos. Segure o ritmo.",
	"guidedRuns.tempo25.cue5": "Faltam dois minutos em tempo. Mantenha-se fluido.",
	"guidedRuns.tempo25.cue6": "Alivie. Cinco minutos leves para desaquecer.",
	"guidedRuns.tempo25.cue7": "Faltam dois minutos. Traga a frequência cardíaca de volta para baixo.",
	"guidedRuns.tempo25.cue8": "Concluído. Caminhe e alongue. Ótimo trabalho.",
